\begin{equation*}
\mq_\alpha^{(s)}:(\bcS_\alpha^s, \bomega_\alpha^s, \bD_\alpha^s,
\bJ_\alpha^s)\stackrel{\sim}{\rightarrow} (\cS^{\varphi^{\alpha}},
\omega^{\varphi^{\alpha}}, D^{\varphi^{\alpha}},
J^{\varphi^{\alpha}})\, .
